"""Deterministic layered discovery of xg configuration."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def xg_directories(cwd: str | Path = ".") -> list[Path]:
    """Return configuration directories from least to most specific."""
    cwd = Path(cwd).resolve()
    candidates: list[Path] = [Path.home() / ".xg"]
    ancestors = list(cwd.parents)[::-1] + [cwd]
    for directory in ancestors:
        candidate = directory / ".xg"
        if candidate not in candidates:
            candidates.append(candidate)
    return [path for path in candidates if path.is_dir()]


def _merge(base: dict[str, Any], overlay: dict[str, Any]) -> dict[str, Any]:
    result = dict(base)
    for key, value in overlay.items():
        if isinstance(result.get(key), dict) and isinstance(value, dict):
            result[key] = _merge(result[key], value)
        else:
            # Lists and scalar values are replacement values. This keeps
            # precedence deterministic and avoids surprising list unions.
            result[key] = value
    return result


def load(cwd: str | Path = ".") -> dict[str, Any]:
    """Load ``config.json`` from all applicable .xg directories."""
    config: dict[str, Any] = {}
    for directory in xg_directories(cwd):
        path = directory / "config.json"
        if not path.is_file():
            continue
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise RuntimeError(f"invalid xg configuration: {path}: {exc}") from exc
        if not isinstance(value, dict):
            raise RuntimeError(f"xg configuration must be an object: {path}")
        config = _merge(config, value)
    return config


def load_agent(name: str, cwd: str | Path = ".") -> dict[str, Any]:
    """Load one agent profile with the nearest profile taking precedence."""
    profile: dict[str, Any] = {}
    found = False
    for directory in xg_directories(cwd):
        path = directory / "agents" / f"{name}.json"
        if not path.is_file():
            continue
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise RuntimeError(f"invalid xg agent profile: {path}: {exc}") from exc
        if not isinstance(value, dict):
            raise RuntimeError(f"xg agent profile must be an object: {path}")
        profile = _merge(profile, value)
        found = True
    if not found:
        raise RuntimeError(f"agent profile not found: {name}")
    return profile

"""Deterministic workspace reading and file selection.

Public API:
    FileEntry
    files(root) -> list[FileEntry]
    context(root) -> str
    resolve(root, name) -> Path

All files are ordered by modification time, oldest first. Hidden metadata,
VCS directories, and binary files are omitted from the agent context.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
import subprocess


@dataclass(frozen=True)
class FileEntry:
    """One readable workspace file and its deterministic metadata."""

    path: str
    mtime_ns: int
    content: str


def files(root: str | Path) -> list[FileEntry]:
    """Read every readable text file below *root*, oldest modification first."""
    root = Path(root).resolve()
    entries: list[FileEntry] = []
    candidates = []
    for path in root.rglob("*"):
        if not path.is_file() or any(part in {".git", ".xg", "__pycache__", ".venv", "venv"} for part in path.relative_to(root).parts):
            continue
        candidates.append(path)
    ignored = _gitignored(root, [path.relative_to(root).as_posix() for path in candidates])
    for path in candidates:
        if path.relative_to(root).as_posix() in ignored:
            continue
        try:
            data = path.read_bytes()
            if b"\0" in data:
                continue
            text = data.decode("utf-8")
            stat = path.stat()
        except (OSError, UnicodeDecodeError):
            continue
        entries.append(FileEntry(path.relative_to(root).as_posix(), stat.st_mtime_ns, text))
    return sorted(entries, key=lambda item: (item.mtime_ns, item.path))


def _gitignored(root: Path, names: list[str]) -> set[str]:
    """Return paths excluded by the workspace's .gitignore rules."""
    if not names:
        return set()
    try:
        result = subprocess.run(
            ["git", "check-ignore", "-z", "--stdin"],
            cwd=root,
            input="\0".join(names), text=True, capture_output=True, check=False,
        )
    except OSError:
        return set()
    return {name for name in result.stdout.split("\0") if name}


def context(root: str | Path) -> str:
    """Build the complete deterministic forced-read context for *root*."""
    entries = files(root)
    if not entries:
        return "(workspace contains no readable files)"
    sections = []
    for entry in entries:
        sections.append(f"=== {entry.path} | mtime_ns: {entry.mtime_ns} ===\n{entry.content}")
    return "\n\n".join(sections)


def resolve(root: str | Path, name: str) -> Path:
    """Resolve a selected relative file and reject paths outside *root*."""
    root = Path(root).resolve()
    path = (root / name).resolve()
    if not path.is_relative_to(root):
        raise ValueError("file path is outside the workspace")
    if not path.is_file():
        raise FileNotFoundError(name)
    return path

"""Initialization of a local .xg subproject."""

from __future__ import annotations

import json
import subprocess
import sys
import venv
from pathlib import Path


def _ensure_ignored(project: Path) -> None:
    """Ensure the local xg environment is not committed."""
    path = project / ".gitignore"
    try:
        content = path.read_text(encoding="utf-8") if path.exists() else ""
    except OSError as exc:
        raise RuntimeError(f"could not read {path}: {exc}") from exc
    if any(line.strip().rstrip("/") == ".xg/.venv" for line in content.splitlines()):
        return
    prefix = content if not content or content.endswith("\n") else content + "\n"
    separator = "" if not prefix or prefix.endswith("\n\n") else "\n"
    try:
        path.write_text(prefix + separator + ".xg/.venv/\n", encoding="utf-8")
    except OSError as exc:
        raise RuntimeError(f"could not update {path}: {exc}") from exc


def _package_root() -> Path | None:
    """Repo root containing this checkout's pyproject.toml, if any."""
    for parent in Path(__file__).resolve().parents:
        if not (parent / "pyproject.toml").is_file():
            continue
        if (parent / "src" / "xg" / "init.py").is_file() or (parent / "xg" / "init.py").is_file():
            return parent
    return None


def initialize(cwd: str | Path = ".") -> int:
    """Create ``.xg` config and a private environment containing xg."""
    project = Path(cwd).resolve()
    try:
        _ensure_ignored(project)
    except RuntimeError as exc:
        print(f"xg init: {exc}", file=sys.stderr)
        return 1
    directory = project / ".xg"
    environment = directory / ".venv"
    config = directory / "config.json"
    directory.mkdir(parents=True, exist_ok=True)

    if config.exists():
        try:
            value = json.loads(config.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            print(f"xg init: invalid existing config.json: {exc}", file=sys.stderr)
            return 1
        if not isinstance(value, dict):
            print("xg init: config.json must contain an object", file=sys.stderr)
            return 1
    else:
        config.write_text("{}\n", encoding="utf-8")

    if not environment.exists():
        print(f"creating {environment}")
        venv.EnvBuilder(with_pip=True, clear=False).create(environment)

    python = environment / ("Scripts/python.exe" if sys.platform == "win32" else "bin/python")
    package_root = _package_root()
    package = str(package_root) if package_root else "xg"
    print("installing xg into the local environment")
    try:
        subprocess.run([str(python), "-m", "pip", "install", "--upgrade", package], check=True)
    except subprocess.CalledProcessError as exc:
        print(f"xg init: could not install xg: {exc}", file=sys.stderr)
        return exc.returncode or 1

    print(f"initialized {directory}")
    print(f"python: {python}")
    print(f"config: {config}")
    return 0

"""Small SDK for defining deterministic xg tools.

Tool modules under ``.xg/tools`` can use this module without importing the CLI.
A tool is just a name, an OpenAI-compatible schema, and a Python callable.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable

from xg.workspace import context as workspace_context


@dataclass
class ToolContext:
    """Execution context supplied to every registered tool."""

    root: Path
    values: dict[str, Any] = field(default_factory=dict)


@dataclass
class ToolResult:
    """Explicit result returned to the model and session recorder."""

    content: str
    ok: bool = True

    def __str__(self) -> str:
        return self.content


@dataclass
class Tool:
    name: str
    description: str
    parameters: dict[str, Any]
    function: Callable[..., Any]

    def schema(self) -> dict[str, Any]:
        return {"type": "function", "function": {
            "name": self.name,
            "description": self.description,
            "parameters": self.parameters,
        }}


class ToolRegistry:
    """Ordered registry of tools exposed to one agent turn."""

    def __init__(self, context: ToolContext):
        self.context = context
        self._tools: dict[str, Tool] = {}

    def register(self, tool: Tool) -> Tool:
        if tool.name in self._tools:
            raise ValueError(f"tool already registered: {tool.name}")
        self._tools[tool.name] = tool
        return tool

    def schemas(self, names: set[str] | None = None) -> list[dict[str, Any]]:
        tools = self._tools.values() if names is None else (
            self._tools[name] for name in self._tools if name in names
        )
        return [tool.schema() for tool in tools]

    def call(self, name: str, arguments: str | dict[str, Any]) -> ToolResult:
        if name not in self._tools:
            raise ValueError(f"unknown tool: {name}")
        args = json.loads(arguments) if isinstance(arguments, str) else arguments
        result = self._tools[name].function(self.context, **args)
        return result if isinstance(result, ToolResult) else ToolResult(str(result))

    def __contains__(self, name: str) -> bool:
        return name in self._tools


def tool(name: str, description: str, parameters: dict[str, Any]):
    """Decorator that turns a function into a :class:`Tool` definition."""
    def decorate(function: Callable[..., Any]) -> Tool:
        return Tool(name, description, parameters, function)
    return decorate


class Context:
    """Explicit context builder used by a profile program."""

    def __init__(self, root: str | Path):
        self.root = Path(root).resolve()
        self.parts: list[str] = []

    def read_workspace(self) -> str:
        """Add the deterministic workspace representation to this context."""
        value = workspace_context(self.root)
        self.parts.append(value)
        return value

    def add(self, value: str) -> None:
        self.parts.append(str(value))

    def render(self) -> str:
        return "\n\n".join(self.parts)


@dataclass
class CallResult:
    """Result of one concrete execution point in a profile."""

    name: str
    arguments: dict[str, Any]
    result: str


class ToolRef:
    """A per-execution-point tool object filled by ``agent.call``."""

    def __init__(self, name: str):
        self.name = name
        self.used = False
        self.arguments: dict[str, Any] = {}
        self.result: str | None = None

    def reset(self) -> "ToolRef":
        self.used = False
        self.arguments = {}
        self.result = None
        return self


# Convenience factories. A profile should create fresh instances per turn.
def select() -> ToolRef:
    return ToolRef("select")


def edit() -> ToolRef:
    return ToolRef("edit")


def new() -> ToolRef:
    return ToolRef("new")


def close() -> ToolRef:
    return ToolRef("close")


def delete() -> ToolRef:
    return ToolRef("delete")


class NoToolCall(RuntimeError):
    """The model replied without the required tool call at an execution point."""

    def __init__(self, message: str, text: str = ""):
        super().__init__(message)
        self.text = text  # the model's plain-text reply, if any


class Agent:
    """Imperative profile runtime; each ``call`` is one model turn."""

    def __init__(self, root: str | Path, prompt: str, chat: Callable, system_prompt: str):
        self.root = Path(root).resolve()
        self.prompt = prompt
        self.chat = chat
        self.system_prompt = system_prompt
        self.context = Context(self.root)
        self.messages: list[dict[str, Any]] = []

    def tool(self, name: str) -> ToolRef:
        """Create a fresh tool execution-point object."""
        return ToolRef(name)

    def call(self, *tool_names: ToolRef) -> str | None:
        """Expose these tool objects and fill the one the model uses.

        A plain-text reply with no tool call is allowed: it is returned as
        a string (and was already streamed to the terminal) and no ToolRef
        is filled. More than one tool call is an error.
        """
        if not tool_names:
            raise ValueError("agent.call() requires at least one tool")
        from xg.tools import ToolState, dispatch, schemas
        from prompt_toolkit import prompt as line_prompt
        state = getattr(self, "_tool_state", None)
        if state is None:
            state = self._tool_state = ToolState(self.root)
        allowed = {tool.name for tool in tool_names}
        from xg.docs import documentation
        user = f"REQUEST:\n{self.prompt}\n\nCONTEXT:\n{self.context.render()}"
        messages = [
            {"role": "system", "content": f"{self.system_prompt}\n\n{documentation()}"},
            {"role": "user", "content": user},
        ]
        message = self.chat(messages, schemas(allowed))
        calls = message.get("tool_calls") or []
        if len(calls) > 1:
            raise NoToolCall(
                f"expected exactly one tool call, got {len(calls)}",
            )
        if not calls:
            # A simple reply is a valid outcome: the text was already
            # streamed to the terminal. No ToolRef is filled, so the
            # imperative program naturally proceeds without tool effects.
            return (message.get("content") or "").strip()
        call = calls[0]
        function = call.get("function") or {}
        name = function.get("name", "")
        if name not in allowed:
            raise RuntimeError(f"tool not allowed at this execution point: {name}")
        print(f"\nProposed tool call: {name}({function.get('arguments', '{}')})")
        try:
            accepted = line_prompt("Accept this tool call? [y/N] ").strip().lower() in {"y", "yes"}
        except (EOFError, KeyboardInterrupt):
            accepted = False
        if not accepted:
            raise RuntimeError(f"tool call rejected: {name}")
        arguments = json.loads(function.get("arguments") or "{}")
        result = dispatch(state, name, function.get("arguments") or "{}")
        selected = next(tool for tool in tool_names if tool.name == name)
        selected.used = True
        selected.arguments = arguments
        selected.result = result


def profile(function: Callable[[Agent], Any]) -> Callable[[Agent], Any]:
    """Mark an ordinary Python function as a xg agent profile."""
    function.__xg_profile__ = True
    return function


def fake_tool_call(name: str, **arguments: Any) -> dict[str, Any]:
    """Create an assistant tool call for deterministic SDK tests."""
    return {
        "id": "fake-call",
        "type": "function",
        "function": {"name": name, "arguments": json.dumps(arguments)},
    }

"""Single-prompt agent loop over the deterministic workspace protocol.

Public API:
    run(root, prompt, chat) -> str
"""

from __future__ import annotations

import json
import sys
from typing import Callable

from prompt_toolkit import prompt as line_prompt

from xg.profiles import AgentProfile, command_profile, default_profile, empty_profile
from xg.sdk import Agent
from xg.tools import ToolState, ToolSpec, dispatch, schemas
from xg.utils import format_patch, tool_patch


class ToolRejected(Exception):
    """Raised when the user rejects a proposed tool call."""


def run(root: str, prompt: str, chat: Callable, profile: AgentProfile | None = None, history: list[dict] | None = None, tools: list[str | ToolSpec] | None = None, session=None, prompt_appended: bool = False) -> str:
    """Run one prompt using a reusable, code-defined agent profile.

    ``session`` (a xg.workflows.Session) makes the conversation log itself
    the context window: every message is appended to its JSONL file and each
    model request is assembled by walking that file — the history is never
    loaded into RAM. ``prompt_appended`` marks that prompt() already wrote
    the request into the session, so only the profile context is added.
    The legacy ``history`` list path and imperative profiles ignore sessions.
    """
    tool_names: list[str] = []
    tool_specs: dict[str, ToolSpec] = {}
    for entry in tools or []:
        if isinstance(entry, ToolSpec):
            tool_names.append(entry.name)
            tool_specs[entry.name] = entry
        else:
            tool_names.append(entry)
    if session is not None:
        # The session-logged loop replaces imperative programs: the file is
        # the conversation, so the message loop below is the only valid path.
        profile = profile or default_profile()
        state = ToolState(root)
        if tools:
            state.restrict(tool_names)
        return _run_logged(root, prompt, chat, profile, state, tool_specs, session, prompt_appended)
    profile = profile or (empty_profile("workflow") if history is not None else default_profile())
    if profile.program is not None:
        program = Agent(root, prompt, chat, profile.system_prompt)
        profile.program(program)
        return ""
    user_content = f"REQUEST:\n{prompt}\n\nPROFILE CONTEXT:\n{profile.context(root)}"
    state = ToolState(root)
    if tools:
        state.restrict(tool_names)
    messages = [
        {"role": "system", "content": profile.system_prompt},
        *(history or []),
        {"role": "user", "content": user_content},
    ]
    while True:
        # Tool exposure is recomputed before every model request. Once a
        # workflow step starts, the model literally cannot see the other tools.
        message = chat(messages, schemas(state.allowed_tools(), overrides=tool_specs))
        messages.append(message)
        calls = message.get("tool_calls") or []
        if not calls:
            return str(message.get("content") or "")
        for call in calls:
            fn = call.get("function") or {}
            name = fn.get("name", "")
            print(f"\nProposed tool call: {name}({fn.get('arguments', '{}')})")
            patch = tool_patch(state, name, fn.get("arguments", "{}"))
            if patch:
                print(format_patch(patch))
            if not _accept_tool():
                raise ToolRejected(name)
            try:
                result = dispatch(state, fn.get("name", ""), fn.get("arguments", "{}"))
            except Exception as exc:
                result = f"tool error: {exc}"
            messages.append({"role": "tool", "tool_call_id": call.get("id"), "content": result})


def _run_logged(root, prompt, chat, profile, state, tool_specs, session, prompt_appended) -> str:
    """Agent loop whose conversation log IS the session file.

    Each model request is built by streaming the session file line-by-line;
    every assistant reply and tool result is appended before the next
    request. RAM holds one message at a time.
    """
    profile = profile or default_profile()
    if not any(m.get("role") == "system" for m in session):  # O(1) RAM walk
        session.add("system", profile.system_prompt)
    # The workspace context is NOT injected here: deterministic file reads
    # are a one-time step of the workflow that needs them (xg-default calls
    # xg.utils.read_workspace(session, root) at its start), never a per-turn
    # injection.
    if not prompt_appended:
        session.add("user", prompt)
    while True:
        message = chat(session, schemas(state.allowed_tools(), overrides=tool_specs))
        session.append(message)
        calls = message.get("tool_calls") or []
        if not calls:
            return str(message.get("content") or "")
        for call in calls:
            fn = call.get("function") or {}
            name = fn.get("name", "")
            print(f"\nProposed tool call: {name}({fn.get('arguments', '{}')})")
            patch = tool_patch(state, name, fn.get("arguments", "{}"))
            if patch:
                print(format_patch(patch))
            if not _accept_tool():
                session.append({"role": "tool", "tool_call_id": call.get("id", ""),
                                "content": f"user rejected the tool call: {name}"})
                raise ToolRejected(name)
            try:
                result = dispatch(state, fn.get("name", ""), fn.get("arguments", "{}"))
            except Exception as exc:
                result = f"tool error: {exc}"
            session.append({"role": "tool", "tool_call_id": call.get("id", ""), "content": result})


def _accept_tool() -> bool:
    """Ask the terminal user to accept or reject one tool call."""
    if not sys.stdin.isatty():
        raise ToolRejected("non-interactive tool call")
    try:
        return line_prompt("Accept this tool call? [y/N] ").strip().lower() in {"y", "yes"}
    except (EOFError, KeyboardInterrupt):
        return False

"""Workflow-authoring utilities.

Public API:
    read_workspace(session, root) -> str
    tool_patch(tool_state, name, arguments) -> str | None
    format_patch(patch, formatter=None) -> str

These are explicit steps a workflow calls when it wants their effect —
not hidden behavior inside cfg.
"""

from __future__ import annotations

import difflib
import hashlib
import json
import os
import subprocess
import tempfile
from pathlib import Path

from xg.workspace import files as _workspace_files

# Deterministic read tool-call id prefix: XG_{ID} where ID is derived from
# the file's workspace-relative path. Seeing any XG_* read call id in the
# window means the deterministic read already happened.
READ_ID_PREFIX = "XG_"
WORKSPACE_MARKER = "# xgdf workspace read"  # legacy one-shot message marker


def _read_id(rel: str) -> str:
    """Deterministic tool-call id for one simulated read of *rel*."""
    return f"{READ_ID_PREFIX}{hashlib.sha1(rel.encode('utf-8')).hexdigest()[:12]}"


def read_workspace(session, root: str | Path) -> str:
    """Perform the deterministic whole-workspace read inside a session window.

    Every readable text file below ``root`` (m-time ordered, hidden
    metadata and gitignored paths excluded) becomes one *simulated* read
    tool call: a single assistant message carrying one ``read`` tool call
    per file, each with a deterministic ``XG_{ID}`` tool-call id derived
    from the file's workspace-relative path, followed by one tool result
    per call holding the file's content. Nothing is executed — the calls
    and results are written straight into the session log.

    This happens exactly once per window: any existing ``XG_*`` read
    tool-call id (or legacy one-shot workspace message) skips the read.

    Returns the number of files read (0 when deduped).
    """
    for message in session:  # O(1) RAM walk, tool results stream past
        if WORKSPACE_MARKER in str(message.get("content") or ""):
            return 0
        for call in message.get("tool_calls") or []:
            if str(call.get("id") or "").startswith(READ_ID_PREFIX):
                return 0
    entries = _workspace_files(root)
    if not entries:
        return 0
    for entry in entries:
        tool_id = _read_id(entry.path)
        session.append(
            {
                "role": "assistant",
                "content": None,
                "tool_calls": [
                    {
                        "id": tool_id,
                        "type": "function",
                        "function": {
                            "name": "read",
                            "arguments": json.dumps({"path": entry.path}),
                        },
                    }
                ],
            }
        )
        session.append(
            {
                "role": "tool",
                "tool_call_id": tool_id,
                "content": entry.content,
            }
        )
    return len(entries)


# ---- git patches for unapplied tool calls -------------------------------


def _git_patch(old: Path | None, new: Path, rel: str) -> str | None:
    """Render a git patch between two file states without applying it.

    ``git diff --no-index`` works outside any repository and emits real git
    patch text (diff --git headers, ---/+++ lines). ``old`` may be None for
    file creation (diffed against /dev/null, producing new-file headers).
    Temp paths are rewritten to a/<rel> and b/<rel> in the output.
    """
    command = ["git", "diff", "--no-index", "--binary"]
    try:
        if old is None:
            command += ["/dev/null", str(new)]
        else:
            command += [str(old), str(new)]
        result = subprocess.run(command, capture_output=True, text=True, check=False)
    except OSError:
        return None
    patch = result.stdout
    if not patch.strip():  # exit code 1 means "differ", which is expected
        return None
    if old is not None:
        # output is "a" + "/abs/path" (git adds the a/ b/ prefixes itself)
        patch = patch.replace(str(old), f"/{rel}")
    return patch.replace(str(new), f"/{rel}")


def _fallback_patch(old_text: str, new_text: str, a_name: str, b_name: str) -> str:
    """difflib fallback when git is unavailable — same unified format."""
    diff = difflib.unified_diff(
        old_text.splitlines(keepends=True), new_text.splitlines(keepends=True),
        fromfile=f"a/{a_name}", tofile=f"b/{b_name}",
    )
    return "".join(diff)


def tool_patch(tool_state, name: str, arguments: str | dict) -> str | None:
    """Render a git patch for an edit/new/delete tool call before it runs.

    The patch previews what the tool WILL do — nothing is applied. Returns
    None when the call produces no patch (unknown tool, bad arguments, or
    edit() with a non-unique old_text).
    """
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments or "{}")
        except json.JSONDecodeError:
            return None
    root: Path = tool_state.root

    old_text = new_text = None
    rel = None
    if name == "edit":
        if tool_state.selected is None:
            return None
        try:
            current = tool_state.selected.read_text(encoding="utf-8")
            if current.count(arguments.get("old_text", "")) != 1:
                return None
        except OSError:
            return None
        rel = tool_state.selected.relative_to(root).as_posix()
        old_text, new_text = current, current.replace(arguments.get("old_text", ""), arguments.get("new_text", ""), 1)
    elif name == "new":
        rel = arguments.get("name", "")
        new_text = arguments.get("content", "")
        old_text = None  # /dev/null side: real new-file headers
    elif name == "delete":
        rel = arguments.get("path", "")
        try:
            old_text = (root / rel).read_text(encoding="utf-8")
        except OSError:
            return None
        new_text = ""
        # deleted files are best shown as pure removals
    else:
        return None

    with tempfile.TemporaryDirectory(prefix="xg-patch-") as directory:
        temp = Path(directory)
        if old_text is not None:
            old_path = temp / "a" / rel
            old_path.parent.mkdir(parents=True, exist_ok=True)
            old_path.write_text(old_text, encoding="utf-8")
        else:
            old_path = None
        new_path = temp / "b" / rel
        new_path.parent.mkdir(parents=True, exist_ok=True)
        new_path.write_text(new_text or "", encoding="utf-8")
        patch = _git_patch(old_path, new_path, rel)
    return patch if patch is not None else _fallback_patch(old_text or "", new_text or "", rel, rel)


def _default_formatter() -> str | None:
    """External diff formatter from $XG_DIFF_FORMATTER or config.json."""
    from xg.config import load

    value = os.environ.get("XG_DIFF_FORMATTER")
    if value:
        return value
    return load(".").get("diff_formatter")


def format_patch(patch: str, formatter: str | None = None) -> str:
    """Color a git patch: via an external formatter subprocess if configured.

    ``formatter`` (or $XG_DIFF_FORMATTER, or the ``diff_formatter`` config
    key) is a shell command receiving the patch on stdin — e.g. ``delta``
    or ``diffr``. If the formatter fails, the plain patch is returned.
    """
    if not patch:
        return patch
    formatter = formatter or _default_formatter()
    if formatter:
        try:
            result = subprocess.run(
                formatter, shell=True, input=patch,
                capture_output=True, text=True, check=False,
            )
            if result.returncode == 0 and result.stdout.strip():
                return result.stdout
        except OSError:
            pass
    # Built-in ANSI coloring fallback.
    lines = []
    for line in patch.splitlines():
        if line.startswith("+") and not line.startswith("+++"):
            lines.append(f"\033[32m{line}\033[0m")
        elif line.startswith("-") and not line.startswith("---"):
            lines.append(f"\033[31m{line}\033[0m")
        elif line.startswith("@@"):
            lines.append(f"\033[36m{line}\033[0m")
        else:
            lines.append(line)
    return "\n".join(lines)

"""Near-deterministic workflow programs.

Public API:
    Session                 # a writable context window
    AgentConfig(model=None, session=None)   # the ``cfg`` handed to workflows
    load_workflow(name, cwd) -> callable
    run_workflow(name, cwd, cfg=None) -> int

A workflow is a Python file at ``.xg/workflows/<name>.py`` exposing
``run(cfg)`` as a generator that yields operations:

    def run(cfg):
        session = cfg.get_session()
        yield WorkspaceRead(session)
        request = yield Prompt(session, "your request")
        yield Agent(session, request, tools=["select", "edit"])

The runner walks through operations, skipping completed steps on resume.
Each yield is a checkpoint: the runner captures state and restores it
when resuming.

Rules:
  * ``cfg.shell()`` is a trusted author step, never available to the model;
    the agent stays limited to the constrained file tools.
  * ``AgentConfig.model`` defaults to the configured xg model.
  * ``AgentConfig()`` without an explicit session lazily creates one; keep
    the config around and every ``cfg.agent()`` call shares that context
    window. Without a session, each call runs on a temporary context.
"""

from __future__ import annotations

